"use strict";(self.webpackChunksketch_blog=self.webpackChunksketch_blog||[]).push([[7210],{2044(a,e,t){t.r(e),t.d(e,{_pageData:()=>h,default:()=>p});var n=t(641);const h=JSON.parse('{"path":"/notes/%E4%B9%A6%E5%BD%B1%E9%9F%B3%E6%B8%B8/%E8%A7%86%E9%A2%91/%E5%AE%87%E5%AE%99%E6%8E%A2%E7%B4%A2%E7%BC%96%E8%BE%91%E9%83%A8.html","title":"宇宙探索编辑部","lang":"zh-CN","frontmatter":{"title":"宇宙探索编辑部","date":"2023-05-25T00:00:00.000Z","tags":["影视"]},"git":{},"filePathRelative":"notes/书影音游/视频/宇宙探索编辑部.md"}'),s={name:"宇宙探索编辑部.md"},p=(0,t(6262).A)(s,[["render",function(a,e,t,h,s,p){return(0,n.uX)(),(0,n.CE)("div",null,[...e[0]||(e[0]=[(0,n.Fv)('<h1 id="宇宙探索编辑部" tabindex="-1"><a class="header-anchor" href="#宇宙探索编辑部"><span>宇宙探索编辑部</span></a></h1><p>致力于探索地外文明的唐志军在穷困潦倒的情况下，发现了一些异常现象，卖了自己珍藏了30年的宇航服，和其他三位伙伴去探究真相的一个故事。</p><p>看完了也不太清楚这部片子讲了什么东西。</p><h4 id="人类存在在这个宇宙中的意义是什么" tabindex="-1"><a class="header-anchor" href="#人类存在在这个宇宙中的意义是什么"><span>人类存在在这个宇宙中的意义是什么</span></a></h4><p>这是唐志军的女儿自杀前问唐志军的问题，电影中似乎也给出了回答：活着就是存在的意义</p><p>从一开始见到孙一通嚼的螺旋状的泡泡糖，到最后婚礼时演讲出现的螺旋dna画面。我觉得就是在说，活着/繁衍就是人类存在的意义。</p><p>可惜当时唐志军并没有给出女儿答案，要不或许有可能挽回女儿的一条命。不过希望依然不大，因为他女儿患了抑郁症，不是单纯因为找不到存在的意义而自杀的。</p><h4 id="不理解-不原谅" tabindex="-1"><a class="header-anchor" href="#不理解-不原谅"><span>不理解，不原谅</span></a></h4>',8)])])}]])}}]);